export const meta = {
  name: 'fail-schema-retries',
  description: 'Round-2 debugger probe: unsatisfiable schema (minLength > maxLength) to force structured-output retries.',
  phases: [{ title: 'Probe' }],
}
phase('Probe')
const IMPOSSIBLE = {
  type: 'object',
  properties: {
    x: { type: 'string', minLength: 10, maxLength: 5 },
  },
  required: ['x'],
  additionalProperties: false,
}
const r = await agent('Return an object with a string field x of any value.', {
  label: 'impossible-schema',
  schema: IMPOSSIBLE,
})
return { result: r }
